The following observations will be useful throughout this section. Recall the definition of \emph{strong} envy from \cref{def:envy}.

\begin{observation}\label{obs:EFX_one_good}
    An agent that has only received one good is not strongly envied by any agent.
\end{observation}

\begin{observation}\label{obs:EFX_zero_value}
    For agents $i,j$, if $i$ does not strongly envy~$j$ and $j$ has received a good $g$ s.t.~$v_i(g) = 0$, then $i$ does not envy $j$.
\end{observation}

\label{subsec:EF->EFX}


It was first proven by Christodoulou et al.~\cite{EFXgraphs} that \EFXo\ is NP-complete even with symmetric valuations;
this hardness persists even for simple graphs of vertex cover number $8$ or for multigraphs consisting of $10$ vertices,
where the problem was proven to be weakly NP-complete (Deligkas et al.~\cite{ijcai/DeligkasEGK25}).
In a follow-up work, Afshinmehr et al.~\cite{AfshinmehrDKMR25} show NP-completeness even for symmetric instances on bipartite multigraphs with $8$ vertices.
Here we present a reduction from \EFo\ to \EFXo\ that, along with \cref{subsec:EF:hardness},
will allow us to complement and improve upon the aforementioned results. See \cref{fig:EF_to_EFX_main} for an overview of our reduction.




\begin{theoremrep}[\appsymb]\label{thm:efo->efxo}
    There is a polynomial-time, logarithmic-space reduction from \EFo\ to \EFXo\ that only adds 2 vertices
    and edges of symmetric binary valuation.
    The reduction preserves simplicity.
\end{theoremrep}

\begin{proof}
    Let $\mathcal{I}=(G=(V,E),\{v_i\}_{i\in V})$ be an instance of \EFo.
    We build an $\EFXo$ instance $\mathcal{I'}$ by adding two vertices $d_1,d_2$ to $G$, each connected with every $v\in V$ by edges of weight $0$ (for both endpoints). Additionally, we connect $d_1$ and $d_2$ with an edge $e^*$ of weight $1$ (for both endpoints). Let $G'=(V',E')$ be the resulting graph of~$\mathcal{I}'$ (see \cref{fig:EF_to_EFX}).



    We prove that if $\mathcal{I}$ has an EF orientation, then $\mathcal{I}'$ has an EFX orientation. Take an EF orientation $O$ of $\mathcal{I}$ and extend it by orienting the edges in $E'\setminus E$ as follows to obtain an orientation~$O'$.
    Orient $e^*$ towards $d_1$. Then, orient all other edges incident to $d_2$ towards $d_2$ and all other edges incident to $d_1$ away from $d_1$. By \cref{obs:EFX_one_good}, $d_1$ is not strongly envied by any $v\in V'$; the same holds for $d_2$ since all of its allocated edges are of weight $0$ (for both endpoints). Additionally, $d_1$ does not envy any other vertex, since
    it has received its unique incident edge with non-zero weight. Observe that $d_2$ only envies $d_1$, since it has received all of its incident edges except $e^*$ (however, this envy is not strong, by \cref{obs:EFX_one_good}). Since $O$ is EF, it holds that $u$ does not envy $v$ for all $u,v \in V$, implying that $u$ does not strongly envy $v$. From all the above we infer that $O'$ is EFX.

    We now prove the converse: if $\mathcal{I}'$ has an EFX orientation, then $\mathcal{I}$ has an EF orientation. Take an EFX orientation $O'$ of $\mathcal{I}'$. Without loss of generality, assume $e^*$ is oriented towards $d_1$ in $O'$. Then, for $O'$ to be an EFX orientation, $d_1$ must not receive any other edge (otherwise $d_2$ would strongly envy $d_1$), implying that all other edges incident to $d_1$ are oriented away from $d_1$ in $O'$. Hence, every vertex $v\in V$ has received a zero-weight edge in $O'$. For all $u,v\in V$, $u$ does not strongly envy $v$ because $O'$ is EFX; by \cref{obs:EFX_zero_value}, this implies that $u$ does not envy $v$. Hence, orienting all edges in $E$ in accordance to $O'$ results in an EF orientation $O$ of $\mathcal{I}$.

    The reduction described uses logarithmic space,
    \footnote{This property is essential for the XNLP- and XALP-hardness in \cref{cor:EFXo_W1}.}
    since only two vertices and $\bO(n)$ edges of polynomial weight are added to the graph.
\end{proof}

Combining \cref{thm:efo->efxo} with the hardness results in \cref{subsec:EF:hardness} leads to \cref{cor:EFXo:weak_NPh,cor:EFXo_W1}.

\begin{corollary}\label{cor:EFXo:weak_NPh}
    {\EFXo} is weakly NP-complete even restricted to
    \begin{itemize}
        \item simple symmetric instances of vertex cover number $4$,
        \item symmetric instances with $4$ vertices.
    \end{itemize}
\end{corollary}

\begin{corollary}\label{cor:EFXo_W1}
    \EFXo\ is  W[1]-hard parameterized by vertex cover number,
    XNLP-hard parameterized by pathwidth,
    and XALP-hard parameterized by treewidth,
    even restricted to simple symmetric instances with polynomially-bounded weights.
    Furthermore, for such instances, {\EFXo} does not admit a $n^{o(\vc)}$ algorithm under the ETH,
    where $\vc$ denotes the vertex cover number of the input graph.
\end{corollary}

We now compare \cref{cor:EFXo:weak_NPh,cor:EFXo_W1} with existing literature.
\cref{cor:EFXo:weak_NPh} improves upon the respective constants of 8 and 10 from Deligkas et al.~\cite{ijcai/DeligkasEGK25}, as well as the result for multigraphs with~8 vertices by Afshinmehr et al.~\cite{AfshinmehrDKMR25}.
As for \cref{cor:EFXo_W1}, it presents the first hardness results for instances with polynomially-bounded weights and small vertex cover,
and along with the algorithm of \cref{subsec:EFXo:tw}, it answers an open question of Deligkas et al.~\cite{ijcai/DeligkasEGK25} regarding the hardness of {\EFXo} in this setting.

\begin{theorem}
    Let $G=(V,E),w_1,\dots,w_n$ an instance of $\EFo$. Let $k$ such that the maximum weight of the instance is bounded by $k$, and for all $i,j\in V$, $W_{i,j}^i,W_{i,j}^k\leq k$ or $W_{i,j}^i,W_{i,j}^k\geq 3k-1$. Then, the instance has an EFX orientation if and only if it has a k-balanced EFX orientation.
\end{theorem}
